const VIEWBOXES = {
  full: "0 0 400 270",
  mark: "116 58 168 114",
  wordmark: "81.3 188.8 245.4 26",
} as const;

type LogoProps = SVGProps<SVGSVGElement> & {
  /** `full` is the lockup; `mark` the jacket monogram; `wordmark` the name alone. */
  variant?: keyof typeof VIEWBOXES;
  ref?: Ref<SVGSVGElement>;
};

export function Logo({ variant = "full", ref, ...props }: LogoProps) {
  return (
    <svg
      ref={ref}
      viewBox={VIEWBOXES[variant]}
      fill="currentColor"
      role="img"
      aria-label={variant === "full" ? "Lune Limo, private chauffeur" : "Lune Limo"}
      {...props}
    >
      {variant !== "wordmark" && (
        <g data-logo="mark">
          {PIECES.rects.map(([x, y, w, h], i) => (
            <rect key={`r${i}`} data-piece x={x} y={y} width={w} height={h} />
          ))}
          {PIECES.polygons.map((points, i) => (
            <polygon key={`p${i}`} data-piece points={points} />
          ))}
          <g fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinejoin="round">
            {PIECES.lines.map((d, i) => (
              <path key={`l${i}`} data-piece data-line d={d} />
            ))}
          </g>
          <g fill="none" stroke="currentColor" strokeWidth={1} strokeLinecap="round">
            {PIECES.seams.map((d, i) => (
              <path key={`s${i}`} data-piece data-line d={d} />
            ))}
          </g>
        </g>
      )}
      {variant !== "mark" && (
        <g data-logo="words">
          <path fillRule="evenodd" d={WORDMARK} />
          {variant === "full" && (
            <>
              <rect x="72" y="237" width="28" height="0.75" />
              <rect x="300" y="237" width="28" height="0.75" />
              <text
                x="202"
                y="241"
                textAnchor="middle"
                fontSize="11"
                letterSpacing="4"
                style={{ fontFamily: "var(--font-inter), sans-serif" }}
              >
                PRIVATE CHAUFFEUR
              </text>
            </>
          )}
        </g>
      )}
    </svg>
  );
}
